// Hook Library — 700 annotated hooks for Startoor.
// Warm editorial. Real, copyable, tokenized where natural.
// Patterns: curiosity-gap, contrarian, stat-reveal, specific-number,
// callback-promise, pattern-interrupt, story-open, false-consensus,
// problem-declaration, stakes-raise, authority-stack, concrete-image,
// time-bound, enemy-callout, reversal.

export type HookPlatform =
  | "twitter"
  | "linkedin"
  | "youtube"
  | "newsletter"
  | "cold-email"
  | "tiktok";

export type HookPattern =
  | "curiosity-gap"
  | "contrarian"
  | "stat-reveal"
  | "specific-number"
  | "callback-promise"
  | "pattern-interrupt"
  | "story-open"
  | "false-consensus"
  | "problem-declaration"
  | "stakes-raise"
  | "authority-stack"
  | "concrete-image"
  | "time-bound"
  | "enemy-callout"
  | "reversal";

export type HookVertical =
  | "saas"
  | "creator"
  | "b2b"
  | "dtc"
  | "agency"
  | "education"
  | "fitness"
  | "finance";

export type HookLength = "short" | "medium" | "long";

export type Hook = {
  id: string;
  hook: string;
  platform: HookPlatform;
  pattern: HookPattern;
  vertical?: HookVertical;
  length: HookLength;
  annotation: string;
};

// Helper for terse ids.
const h = (
  id: string,
  hook: string,
  platform: HookPlatform,
  pattern: HookPattern,
  length: HookLength,
  annotation: string,
  vertical?: HookVertical,
): Hook => ({ id, hook, platform, pattern, length, annotation, vertical });

